css:
:root{box-sizing:border-box;--pb:#101114;--pf:#eceef2;--pm:#9aa0ad;--pc:#181a20;--pl:#2a2d36;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:light){:root:not([data-theme=dark]){--pb:#f5f6f9;--pf:#14161c;--pm:#5d6472;--pc:#fff;--pl:#d9dde6}}
*{box-sizing:border-box}
body{margin:0;background:var(--pb);color:var(--pf);font:15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;padding:24px 18px 60px;max-width:1000px;margin-inline:auto}
h1{font-size:30px;margin:0 0 6px;letter-spacing:-.02em}
p.l{color:var(--pm);max-width:72ch;margin:0 0 18px}
button{font:inherit;border:1px solid var(--pl);background:var(--pc);color:var(--pf);padding:7px 14px;border-radius:99px;cursor:pointer}
button.on{background:var(--pf);color:var(--pb)}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
#desc{color:var(--pm);margin:0 0 20px}
.wrap{display:grid;grid-template-columns:minmax(0,340px) 1fr;gap:28px;align-items:start}
@media(max-width:760px){.wrap{grid-template-columns:1fr}}
.stw{container-type:inline-size;width:100%}
.ctl{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
li{border:1px solid var(--pl);background:var(--pc);border-radius:12px;padding:10px 12px;cursor:pointer}
li.on{border-color:var(--pf)}
li b{display:flex;justify-content:space-between;font-size:14px}
li span{color:var(--pm);font-size:12px}
li p{margin:4px 0 0;font-size:13.5px}
.st{position:relative;aspect-ratio:9/16;border-radius:18px;overflow:hidden;background:var(--bg);color:var(--fg);font-size:4.6cqw;line-height:1.3;border:1px solid var(--pl)}
.a{position:absolute}.ctr{text-align:center}.mut{color:var(--mut)}.ac{color:var(--ac)}
.mono{font-family:ui-monospace,"SF Mono",Menlo,Consolas,monospace;font-size:.85em}
.card{background:var(--card);border:var(--bw,1px) solid var(--bd);border-radius:1em;padding:.9em}
.chip{display:inline-block;border:var(--bw,1px) solid var(--bd);border-radius:99px;padding:.15em .7em;font-size:.8em;color:var(--mut);background:var(--card)}
.badge{display:inline-block;background:var(--ac);color:var(--bg);font-weight:800;font-size:.8em;padding:.25em .7em;border-radius:.4em}
.row{display:flex;align-items:center;gap:.6em;background:var(--card);border:var(--bw,1px) solid var(--bd);border-radius:.7em;padding:.7em .8em;font-weight:700}
.num{width:1.6em;height:1.6em;border-radius:50%;background:var(--ac);color:var(--bg);display:inline-flex;align-items:center;justify-content:center;font-size:.85em;flex:none}
.col{display:flex;flex-direction:column;gap:.7em}
.big{font-size:3.4em;font-weight:900;line-height:1}
.bar2{height:.7em;border-radius:.4em;background:rgba(127,127,127,.3);overflow:hidden}
.sx{display:block;height:100%;background:var(--ac);transform-origin:left;transform:scaleX(0)}
.bb{max-width:80%;padding:.6em .9em;border-radius:1.1em;background:var(--card)}
.me{background:var(--ac);color:#fff;margin-left:auto}
.key{display:inline-flex;align-items:center;justify-content:center;font-size:1.9em;font-weight:700;width:1.6em;height:1.6em;background:linear-gradient(#444853,#262930);border-radius:.25em;box-shadow:0 .12em 0 #0a0b0e;color:#fff}
.add{background:rgba(74,222,128,.18);color:#4ade80}.del{background:rgba(248,113,113,.18);color:#f87171}
.cp{position:absolute;left:6%;right:6%;bottom:11%;text-align:center;font-weight:800;font-size:1.5em;line-height:1.15}
.w{display:inline-block;opacity:0}.k{color:var(--hl)}
.pg{position:absolute;top:.6em;left:.6em;right:.6em;display:flex;gap:.3em;z-index:5}
.pg i{flex:1;height:.25em;border-radius:9px;background:rgba(127,127,127,.4);overflow:hidden}
.pg i.dn{background:var(--fg)}
.pg b{display:block;height:100%;background:var(--fg);transform:scaleX(0);transform-origin:left;animation:fl linear both}
.type{overflow:hidden;white-space:nowrap;width:0}
.wipe{clip-path:inset(0 100% 0 0)}
.st:not(.play) :is(.pop,.slam,.sl){opacity:0}
.play .pop{animation:pop .5s both;animation-delay:var(--d,0s)}
.play .sl{animation:sl .5s both;animation-delay:var(--d,0s)}
.play .slam{animation:sm .35s cubic-bezier(.2,1.4,.4,1) both;animation-delay:var(--d,0s)}
.play .w{animation:up .35s both}
.play .type{animation:type .9s steps(20) both;animation-delay:var(--d)}
.play .sx{animation:fl 1s both;animation-delay:var(--d)}
.play .wipe{animation:wp .8s ease-out both;animation-delay:var(--d)}
.paused *{animation-play-state:paused!important}
@keyframes pop{from{opacity:0;transform:translateY(8px) scale(.96)}to{opacity:1;transform:none}}
@keyframes sl{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes sm{from{opacity:0;transform:scale(2.4)}to{opacity:1;transform:none}}
@keyframes up{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@keyframes type{to{width:var(--w)}}
@keyframes fl{to{transform:none}}
@keyframes wp{to{clip-path:inset(0)}}
@media (prefers-reduced-motion:reduce){.st *{animation-duration:.01s!important}}

